  textTertiary: '#cbd5e1',
  border: '#334155',
  accentGlow: 'rgba(139, 92, 246, 0.5)',
  gradientBackground: 'linear-gradient(135deg, #0f172a 0%, #581c87 50%, #0f172a 100%)',
  gradientText: 'linear-gradient(90deg, #c084fc 0%, #60a5fa 50%, #c084fc 100%)',
};

const spacing = {
  xs: '8px',
  sm: '12px',
  md: '16px',
  lg: '24px',
  xl: '32px',
  xxl: '48px',
  xxxl: '64px',
};

const categories = [
  { name: 'Frontend', color: '#8b5cf6' },
  { name: 'Backend', color: '#60a5fa' },
  { name: 'Database', color: '#a78bfa' },
  { name: 'DevOps', color: '#34d399' },
  { name: 'Cloud', color: '#38bdf8' },
  { name: 'Cybersecurity', color: '#f87171' },
  { name: 'Systems', color: '#94a3b8' },
  { name: 'Software Engineering', color: '#facc15' },
  { name: 'Tools', color: '#fbbf24' },
  { name: 'Project Management', color: '#a3e635' },
  { name: 'Soft Skills', color: '#fb7185' },
  { name: 'Languages', color: '#818cf8' },
];

export default function SkillsPage() {
  const [selectedSkill, setSelectedSkill] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [highlightedConnections, setHighlightedConnections] = useState(new Set());
  const svgRef = useRef();

  const categoryGroups = {};
  skillsData.forEach(skill => {
    if (!categoryGroups[skill.category]) {
      categoryGroups[skill.category] = [];
    }
    categoryGroups[skill.category].push(skill);
  });

  // Determine which skills to display
  const getDisplayedSkills = () => {
    if (selectedSkill) {
      return [selectedSkill];
    }
    if (selectedCategory) {
      return categoryGroups[selectedCategory] || [];
    }
    return skillsData;
  };

  const displayedSkills = getDisplayedSkills();

  // D3 Network Graph
  useEffect(() => {
    if (!svgRef.current) return;
    const width = svgRef.current.clientWidth;
    const height = 600;

    // Create nodes
    const nodes = [
      { id: 'Hubert', label: 'Hubert', type: 'center', category: 'center' },
      ...skillsData.map(skill => ({
        id: skill.id,
        label: skill.name,
        type: 'skill',
        category: skill.category,
      })),
    ];

    // Create links
    const links = [];
    skillsData.forEach(skill => {
      links.push({ source: 'Hubert', target: skill.id });
      skill.connections.forEach(connection => {
        if (skillsData.find(s => s.id === connection)) {
          links.push({ source: skill.id, target: connection });
        }
      });
    });

    // Remove duplicate links
    const uniqueLinks = [];
    const linkSet = new Set();
    links.forEach(link => {
      const key = [link.source, link.target].sort().join('-');
      if (!linkSet.has(key)) {
        uniqueLinks.push(link);
        linkSet.add(key);
      }
    });

    const simulation = d3
      .forceSimulation(nodes)
      .force('link', d3.forceLink(uniqueLinks).id(d => d.id).distance(80))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(40));

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const g = svg
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`)
      .append('g');

    // Links
    const link = g
      .selectAll('line')
      .data(uniqueLinks)
      .enter()
      .append('line')
      .attr('stroke', colors.border)
      .attr('stroke-width', 2)
      .attr('opacity', 0.4);

    // Nodes
    const node = g
      .selectAll('g.node')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(
        d3.drag()
          .on('start', dragStarted)
          .on('drag', dragged)
          .on('end', dragEnded)
      );

    node
      .append('circle')
      .attr('r', d => (d.type === 'center' ? 40 : 25))
      .attr('fill', d => {
        if (d.type === 'center') return colors.purple;
        const cat = categories.find(c => c.name === d.category);
        return cat ? cat.color : colors.blue;
      })
      .attr('opacity', 0.9)
      .attr('stroke', colors.textPrimary)
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (e, d) => {
        if (d.type !== 'center') {
          const skill = skillsData.find(s => s.id === d.id);
          setSelectedSkill(skill);
          setSelectedCategory(null);
          const connected = new Set([d.id, ...skill.connections]);
          setHighlightedConnections(connected);
        }
      })
      .on('mouseover', (e, d) => {
        link.attr('stroke', l =>
          (l.source.id === d.id || l.target.id === d.id) ? colors.purple : colors.border
        );
      })
      .on('mouseout', () => {
        link.attr('stroke', colors.border);
      });

    node
      .append('text')
      .text(d => d.label)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.3em')
      .attr('fill', colors.textPrimary)
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')
      .attr('pointer-events', 'none');

    function dragStarted(e, d) {
      if (!e.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    }

    function dragged(e, d) {
      d.fx = e.x;
      d.fy = e.y;
    }

    function dragEnded(e, d) {
      if (!e.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    }

    simulation.on('tick', () => {
      link
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, []);

  const handleCategoryClick = (categoryName) => {
    setSelectedCategory(selectedCategory === categoryName ? null : categoryName);
    setSelectedSkill(null);
  };

  const handleClearFilters = () => {
    setSelectedSkill(null);
    setSelectedCategory(null);
    setHighlightedConnections(new Set());
  };

  return (
    <div style={styles.container}>
      {/* Hero Section */}
      <section style={styles.heroSection}>
        <h1 style={styles.title}>My Skills & Expertise</h1>
        <p style={styles.introduction}>
          I learn best by building. Each of these skills comes from solving a problem, exploring an idea, 
          or collaborating on something meaningful. My journey spans from cybersecurity fundamentals to 
          full-stack web development, always driven by curiosity and real-world application.
        </p>
      </section>

      {/* Category Overview */}
      <section style={styles.categorySection}>
        <h2 style={styles.sectionTitle}>Skill Categories</h2>
        <div style={styles.categoryGrid}>
          {categories.map(cat => {
            const skillCount = skillsData.filter(s => s.category === cat.name).length;
            const isActive = selectedCategory === cat.name;
            return (
              <div 
                key={cat.name} 
                style={{
                  ...styles.categoryCard,
                  ...(isActive ? styles.categoryCardActive : {}),
                }}
                onClick={() => handleCategoryClick(cat.name)}
              >
                <div style={{ ...styles.categoryDot, backgroundColor: cat.color }} />
                <h3 style={styles.categoryName}>{cat.name}</h3>
                <p style={styles.skillCount}>{skillCount} skills</p>
              </div>
            );
          })}
        </div>
        {(selectedSkill || selectedCategory) && (
          <div style={styles.filterInfo}>
            <p style={styles.filterText}>
              {selectedSkill 
                ? `Showing: ${selectedSkill.name}` 
                : `Showing ${displayedSkills.length} skill(s) from ${selectedCategory}`}
            </p>
            <button 
              onClick={handleClearFilters}
              style={styles.clearButton}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = colors.purple;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = `rgba(139, 92, 246, 0.2)`;
              }}
            >
              Clear Filters
            </button>
          </div>
        )}
      </section>

      {/* Network Graph */}
      <section style={styles.networkSection}>
        <h2 style={styles.sectionTitle}>Skills Network Map</h2>
        <p style={styles.networkDescription}>
          Interactive map of how my skills connect and relate. Click on any skill bubble to highlight its connections.
        </p>
        <div style={styles.networkContainer}>
          <svg ref={svgRef} style={styles.svg} />
        </div>
        <div style={styles.networkLegend}>
          <p style={styles.legendTitle}>Click on any skill to explore its connections. Drag to reposition.</p>
          {selectedSkill && (
            <div style={styles.selectedSkillInfo}>
              <strong>Selected: {selectedSkill.name}</strong>
              <p>Connections: {selectedSkill.connections.map(id => skillsData.find(s => s.id === id)?.name).join(', ')}</p>
            </div>
          )}
        </div>
      </section>

      {/* Skills Detail Cards */}
      <section style={styles.skillsSection}>
        <h2 style={styles.sectionTitle}>
          {selectedSkill 
            ? `${selectedSkill.name}` 
            : selectedCategory 
            ? `${selectedCategory} Skills` 
            : 'Detailed Skills'}
        </h2>
        <div style={styles.skillsContainer}>
          {displayedSkills.map(skill => (
            <div 
              key={skill.id} 
              style={{
                ...styles.skillCard,
                ...(selectedSkill?.id === skill.id ? styles.skillCardActive : {}),
              }}
              onClick={() => {
                setSelectedSkill(skill);
                setSelectedCategory(null);
                const connected = new Set([skill.id, ...skill.connections]);
                setHighlightedConnections(connected);
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-8px)';
                e.currentTarget.style.boxShadow = `0 20px 25px -5px ${colors.accentGlow}`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              <div style={styles.skillCardHeader}>
                <div 
                  style={{
                    ...styles.categoryBadge,
                    backgroundColor: categories.find(c => c.name === skill.category)?.color || colors.blue,
                  }}
                >
                  {skill.category}
                </div>
                <span style={styles.learnedDate}>{skill.learned}</span>
              </div>

              <h3 style={styles.skillName}>{skill.name}</h3>

              {skill.connections.length > 0 && (
                <div style={styles.connectionsContainer}>
                  <p style={styles.skillLabel}>Related Skills:</p>
                  <div style={styles.connectionsTags}>
                    {skill.connections.map(connId => {
                      const connSkill = skillsData.find(s => s.id === connId);
                      return (
                        <span key={connId} style={styles.connectionTag}>
                          {connSkill?.name}
                        </span>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

